const FREEZE_BOUND: Duration = Duration::from_secs(3);

/// Accepts connections and never replies, keeping every socket open.
fn spawn_silent_endpoint() -> (u16, Arc<AtomicUsize>) {
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    let accepted = Arc::new(AtomicUsize::new(0));
    let accepted_in_thread = Arc::clone(&accepted);
    std::thread::spawn(move || {
        let mut held = Vec::new();
        while let Ok((stream, _)) = listener.accept() {
            accepted_in_thread.fetch_add(1, Ordering::SeqCst);
            held.push(stream);
        }
        std::mem::forget(held);
    });
    (port, accepted)
}

