async fn copy_body_to_file(
    output: std::fs::File,
    mut body: Payload,
    format: PayloadType,
) -> Result<std::fs::File, MeilisearchHttpError> {
    let async_file = File::from_std(output);
    let mut buffer = BufWriter::new(async_file);
    let mut buffer_write_size: usize = 0;
    while let Some(result) = body.next().await {
        let byte = result?;

        if byte.is_empty() && buffer_write_size == 0 {
            return Err(MeilisearchHttpError::MissingPayload(format));
        }

        match buffer.write_all(&byte).await {
            Ok(()) => buffer_write_size += 1,
            Err(e) => return Err(MeilisearchHttpError::Payload(ReceivePayload(Box::new(e)))),
        }
    }
```

**Step 3. No layer applies a deadline.** The custom payload extractor accounts for bytes only. The application configuration sets size limits only. The HTTP server sets `disable_signals` and `keep_alive(KeepAlive::Os)` and no client timeout. None of the existing protections bounds a body read, and no cleanup path exists other than the peer acting or the process exiting.

