      .with_max_elapsed_time(Some(std::time::Duration::from_secs(
          *timeouts::BACKOFF_SECONDS,
      )))
      .build();

  backoff::future::retry(backoff, move || {
      // Per-attempt clones omitted.
      async move {
          try_proxy(
              method,
              &url,
